package com.enterprise.fiuadapter.webservice.utils;

import java.util.Calendar;

import org.joda.time.DateTime;
import org.joda.time.DateTimeZone;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;

/**
 * @author manjunathr created at 30-06-2020
 *         <p>
 *         This is the Util class used for the opertations related to Date and time
 */
public class DateTimeUtil {

    /**
     * This method is used to add the number of days and number of months to the given date
     *
     * @param currentMilliSecond
     * @param days
     * @param month
     *
     * @return result DateTime
     */
    public static String getAddedDate( Long currentMilliSecond, int days, int month )
    {
        DateTime date = new DateTime(currentMilliSecond, DateTimeZone.UTC);
        Calendar c = Calendar.getInstance();
        c.setTime(date.toDate());
        c.add(Calendar.DATE, days);
        c.add(Calendar.MONTH, month);
        return getISOTimeStamp(new DateTime(c.getTimeInMillis(), DateTimeZone.UTC).getMillis());
    }

    /**
     * This method returns DateTime in UTC format
     *
     * @return DateTime
     */
    public static DateTime getcurrentUTCTimeStamp()
    {
        return new DateTime(DateTimeZone.UTC);
    }

    public static String getISOTimeStamp( Long milliSecond )
    {
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd'T'hh:mm:ss.SSS'Z'");
        DateTime currentDate = new DateTime(milliSecond, DateTimeZone.UTC);
        return currentDate.toString(formatter);
    }
}
package com.enterprise.fiuadapter.webservice.utils;

import com.enterprise.fiuadapter.webservice.config.ApplicationConfiguration;
import com.enterprise.fiuadapter.webservice.constants.GeneralConstants;
import com.enterprise.fiuadapter.webservice.exceptions.InvalidRequestException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;

@Service
public class TimeStampValidation {
    @Autowired
    ApplicationConfiguration applicationConfigurationBean;

    public boolean validateTimeStamp(String timestamp, String txnId) throws InvalidRequestException {
        //creates a formatter that parses the date in the given format
        try {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
            sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
            Date date = sdf.parse(timestamp);
            long timeInMillis = date.getTime();
            long fifteenAgo = System.currentTimeMillis() - (applicationConfigurationBean.getApplicationConfigurationBean().getTimestampValidity()*60*1000);
            if(new Date().before(date)){
                throw new InvalidRequestException(txnId, GeneralConstants.INVALID_REQUEST,GeneralConstants.TIMESTAMP_FUTURE, HttpStatus.BAD_REQUEST);
            }
            if (timeInMillis < fifteenAgo) {
                return false;
            }
            else{
                return true;
            }
        } catch (ParseException e){
            throw new InvalidRequestException(txnId,GeneralConstants.INVALID_REQUEST,GeneralConstants.DATE_PARSING_ERROR, HttpStatus.BAD_REQUEST);
        }
    }
}
