@Service
public class ConsentNotificationValidationImpl implements ConsentNotificationValidation{

    @Autowired
    TimeStampValidation timeStampValidation;

    @Autowired
    ApplicationConfigurationBean applicationConfigurationBean;

    @Autowired
    ConsentService consentService;

    @Override
    public void validateRequestFields(ConsentNotificationRequest consentNotificationRequest) throws InvalidRequestException, ParseException, DataException {
        String errorMsg = schematicErrorCheck(consentNotificationRequest);

        if(errorMsg.split(",").length == 1 && errorMsg != ""){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,errorMsg+GeneralConstants.ERROR_MESSAGE,HttpStatus.BAD_REQUEST);
        }

        if(!NullEmptyUtils.isNullorEmpty(errorMsg)){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,errorMsg+GeneralConstants.SCHEMATIC_ERROR_MSG,HttpStatus.BAD_REQUEST);
        }

        if(!consentNotificationRequest.getVer().equalsIgnoreCase(applicationConfigurationBean.getFiuConnectVersion())){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.NO_SUCH_VERSION,GeneralConstants.INVALID_VERSION, HttpStatus.NOT_FOUND);
        }

        if(!UUIDGenerator.regaxUUIDvalidation(consentNotificationRequest.getTxnid())){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_FIELD_VALUE, HttpStatus.BAD_REQUEST);
        }

        if(!timeStampValidation.validateTimeStamp(consentNotificationRequest.getTimestamp(), consentNotificationRequest.getTxnid())){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.TIMESTAMP_OLDER, HttpStatus.BAD_REQUEST);
        }

        if(!UUIDGenerator.regaxUUIDvalidation(consentNotificationRequest.getConsentStatusNotification().getConsentHandle())){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_FIELD_VALUE, HttpStatus.BAD_REQUEST);
        }

        if(!consentNotificationRequest.getConsentStatusNotification().getConsentStatus().equals("REJECTED")){
            if(!UUIDGenerator.regaxUUIDvalidation(consentNotificationRequest.getConsentStatusNotification().getConsentId())){
                throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_FIELD_VALUE, HttpStatus.BAD_REQUEST);
            }
        }

        if(!NullEmptyUtils.isNullorEmpty(consentNotificationRequest.getConsentStatusNotification().getConsentStatus())){
            boolean isConsentStatusPresent = false;
            for (Status c : Status.values()) {
                if (c.name().equals(consentNotificationRequest.getConsentStatusNotification().getConsentStatus())) {
                    isConsentStatusPresent = true;
                }
            }
            if(!isConsentStatusPresent){
                throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_CONSENT_STATUS,GeneralConstants.INVALID_CONSENT_STATUS_MSG, HttpStatus.BAD_REQUEST);
            }
        } else {
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_CONSENT_STATUS,GeneralConstants.INVALID_CONSENT_STATUS_MSG, HttpStatus.BAD_REQUEST);
        }

        if(!consentNotificationRequest.getNotifier().getType().equalsIgnoreCase(GeneralConstants.NOTIFIER_AA)){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_NOTIFIER_MSG, HttpStatus.BAD_REQUEST);
        }

        ConsentEntity consentEntity = consentService.getConsentByConsentHandle(consentNotificationRequest.getConsentStatusNotification().getConsentHandle(), consentNotificationRequest.getTxnid());

        if(!NullEmptyUtils.isNullorEmpty(consentEntity.getRequestStatus()) && consentEntity.getRequestStatus().equalsIgnoreCase(GeneralConstants.REQUEST_STATUS)){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_CONSENT_NOTIFICATION_REQUEST+consentEntity.getConsentHandle(), HttpStatus.BAD_REQUEST);
        }

        if(!consentEntity.getAaId().equals(consentNotificationRequest.getNotifier().getId())){
            // This condition is for same consent details for alternate aaId
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_AA, HttpStatus.BAD_REQUEST);
        }

        System.out.println("Consent notification Client id in the api key: "+ MDC.get("key_client_id"));
        String clientId =  MDC.get("key_client_id");
        if(!clientId.equals(consentEntity.getAaId())){
            throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_REQUEST,GeneralConstants.INVALID_AA, HttpStatus.BAD_REQUEST);
        }

        if(!consentEntity.getConsentStatus().equals(Status.PENDING.name())){
            if(!consentEntity.getConsentId().equals(consentNotificationRequest.getConsentStatusNotification().getConsentId())){
                throw new InvalidRequestException(consentNotificationRequest.getTxnid(), GeneralConstants.INVALID_CONSENT_ID,GeneralConstants.INVALID_CONSENT_ID_MESSAGE+consentNotificationRequest.getConsentStatusNotification().getConsentId(), HttpStatus.BAD_REQUEST);
            }
        }

    }

    String schematicErrorCheck(ConsentNotificationRequest consentNotificationRequest){
        HashMap<String, Object> stringObjectHashMap = new HashMap<>();
        String errorMessage ="";
        stringObjectHashMap.put("version", consentNotificationRequest.getVer());
        stringObjectHashMap.put("timeStamp", consentNotificationRequest.getTimestamp());
        stringObjectHashMap.put("txnId", consentNotificationRequest.getTxnid());
        stringObjectHashMap.put("notifier", consentNotificationRequest.getNotifier());
        stringObjectHashMap.put("consentNotificationStatus", consentNotificationRequest.getConsentStatusNotification());
        stringObjectHashMap.put("consentNotificationStatus.consenthandle", consentNotificationRequest.getConsentStatusNotification().getConsentHandle());
        stringObjectHashMap.put("consentNotificationStatus.consentId", consentNotificationRequest.getConsentStatusNotification().getConsentId());
        stringObjectHashMap.put("consentNotificationStatus.consentStatus", consentNotificationRequest.getConsentStatusNotification().getConsentStatus());
        stringObjectHashMap.put("notifier.Id", consentNotificationRequest.getNotifier().getId());
        stringObjectHashMap.put("notifier.type", consentNotificationRequest.getNotifier().getType());
        // iterate map and set the message for empty or null values
        for (String key : stringObjectHashMap.keySet())
        {
            if(NullEmptyUtils.isNull(stringObjectHashMap.get(key)) || stringObjectHashMap.get(key).equals("")){
                if(key.equals("consentNotificationStatus.consentId") &&
                        consentNotificationRequest.getConsentStatusNotification().getConsentStatus().equals("REJECTED")){
                    continue;
                }
                errorMessage = errorMessage + key+",";
            }
        }
        return errorMessage.trim();
    }
}

